package com.bananalab.lite;
public final class Stage44JavaChatCheck{
 static void check(boolean b,String s){if(!b)throw new AssertionError(s);}
 static void expect(String text,String source,String command)throws Exception{JavaChat.Change c=JavaChat.parse(text,source);check(c.handled&&c.error.isEmpty()&&c.command.equals(command),text+" -> "+c.command+" / "+c.error);JavaPatchPolicy.validate(JavaLive.patched(source,c.command));}
 public static void main(String[] args)throws Exception{String base=JavaPatchPolicy.BASE;expect("cambia la celebracion para que salte y despues aplauda",base,"celebracion salta,aplaude");expect("hace que la celebracion sea saltar y aplaudir",base,"celebracion salta,aplaude");expect("cambia el festejo a salto y aplauso",base,"celebracion salta,aplaude");expect("agrega un giro al final de la celebracion",base,"celebracion baila,saluda,salta,gira");expect("quita el baile de la celebracion",base,"celebracion saluda,salta");expect("separa un poco el beso",base,"separacion del beso 1.0");expect("acerca un poco el beso",JavaLive.patched(base,"separacion del beso 2.0"),"separacion del beso 1.0");expect("hace que al besarse queden mas juntos",JavaLive.patched(base,"separacion del beso 2.0"),"separacion del beso 1.0");
  for(String q:new String[]{"cambia la celebracion para que salte y despues vuele","hace la celebracion mas divertida","quita el baile y el saludo y el salto de la celebracion"}){JavaChat.Change c=JavaChat.parse(q,base);check(c.handled&&!c.error.isEmpty()&&c.command.isEmpty(),"unsupported phrase asks instead of dropping instructions");}
  for(String q:new String[]{"que el zorro bese a la banana","pone a Tony azul","como cambio la celebracion","la banana besa al zorro"})check(!JavaChat.parse(q,base).handled,"ordinary scene or question not treated as code change");
  CreatorPersistenceCheck.Fake c=new CreatorPersistenceCheck.Fake();String before=JavaLive.source(c);check(JavaChat.handle(c,"cambia la celebracion para que vuele").text.contains("No cambié"),"unsupported request produces local clarification");check(JavaLive.source(c).equals(before)&&JavaLive.prefs(c).getInt("revision",0)==0,"clarification never edits Java");check(JavaChat.handle(c,"quiero mejorar la app").text.contains("sin escribir código"),"plain-language help");System.out.println("PASS Stage44 conversational Java intent, ordered movement lists, relative edits, undo guidance and no changes for unsupported/scene requests");}
}
